const fsSync=require('node:fs'),temp=fsSync.mkdtempSync(require('node:path').join(require('node:os').tmpdir(),'bluu-instances-ci-')),source=JSON.parse(fsSync.readFileSync('.github/launcher-src/source.json','utf8'));for(const [name,data] of Object.entries(source))fsSync.writeFileSync(require('node:path').join(temp,name),data);
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs/promises'),path=require('node:path'),os=require('node:os');const {normalizeCatalog,visibleInstances,instanceRoot,prepareInstanceRoot,packPrefix}=require(path.join(temp,'instances.cjs')),{ADMIN_UUID}=require(path.join(temp,'theme.cjs')),{verifyGithubManifest}=require(path.join(temp,'pack.cjs'));
const owner={id:ADMIN_UUID},friend={id:'1'.repeat(32)},other={id:'2'.repeat(32)},item=(id,visibility='public',viewers=[])=>({id,name:id,description:'',visibility,viewers,theme:null,access:null});
test('instance visibility filters public, owner-only and selected-account entries, including owner preview',()=>{const catalog={schema:1,instances:[item('kazino'),item('private','owner'),item('friends','selected',[{uuid:friend.id}])]};assert.deepEqual(visibleInstances(catalog,null).map(x=>x.id),['kazino']);assert.deepEqual(visibleInstances(catalog,friend).map(x=>x.id),['kazino','friends']);assert.deepEqual(visibleInstances(catalog,other).map(x=>x.id),['kazino']);assert.equal(visibleInstances(catalog,owner,true).length,3);assert.deepEqual(visibleInstances(catalog,owner,false).map(x=>x.id),['kazino']);assert.deepEqual(visibleInstances(catalog,{id:other.id},true).map(x=>x.id),['kazino']);assert.deepEqual(visibleInstances({schema:1,instances:[]},owner,true),[]);});
test('instance IDs cannot escape storage, use Windows reserved filenames, or collide',()=>{for(const id of ['../mods','a/b','CON','com2','lpt9','a\\b',''])assert.throws(()=>normalizeCatalog({schema:1,instances:[item(id)]}));assert.throws(()=>normalizeCatalog({schema:1,instances:[item('crew'),item('crew')]}));assert.throws(()=>normalizeCatalog({schema:1,instances:[{...item('crew'),name:'bad\nname'}]}));});
test('legacy Kazino storage is preserved and new instances use separate safe directories',async()=>{const root=await fs.mkdtemp(path.join(os.tmpdir(),'bluu-inst-'));try{assert.equal(instanceRoot(root,item('kazino')),path.join(root,'instance'));const a=await prepareInstanceRoot(root,item('crewsafio')),b=await prepareInstanceRoot(root,item('otro'));assert.notEqual(a,b);await fs.writeFile(path.join(a,'world-data'),'saved');await fs.writeFile(path.join(b,'world-data'),'other');assert.equal(await fs.readFile(path.join(a,'world-data'),'utf8'),'saved');assert.equal(packPrefix(item('crewsafio')),'instances/crewsafio');}finally{await fs.rm(root,{recursive:true,force:true});}});
test('a symlink cannot redirect the shared parent or an individual instance directory',async()=>{const root=await fs.mkdtemp(path.join(os.tmpdir(),'bluu-inst-link-'));try{await fs.mkdir(path.join(root,'external'));await fs.symlink(path.join(root,'external'),path.join(root,'instances'),process.platform==='win32'?'junction':'dir');await assert.rejects(prepareInstanceRoot(root,item('crew')),/enlace/);assert.deepEqual(await fs.readdir(path.join(root,'external')),[]);}finally{await fs.rm(root,{recursive:true,force:true});}});
test('instance pack manifests cannot download mods from a different instance or root mods folder',()=>{const repo='owner/repo',version='a'.repeat(40),base={minecraft:'1.20.1',forge:'47.4.0',version,mods:[{file:'mod.jar',sha256:'b'.repeat(64),url:'https://raw.githubusercontent.com/'+repo+'/'+version+'/instances/crew/mods/mod.jar'}]};assert(verifyGithubManifest(base,repo,'instances/crew'));assert.throws(()=>verifyGithubManifest(base,repo,'instances/other'));assert.throws(()=>verifyGithubManifest(base,repo));assert.throws(()=>verifyGithubManifest(base,repo,'../crew'));});
test('instance notices migrate the Kazino default and preserve custom messages',()=>{const {instancePolicy}=require(path.join(temp,'instances.cjs')),{defaults}=require(path.join(temp,'access.cjs'));const crew={...item('crewsafio'),name:'CrewSafío',access:{...defaults}};assert.match(instancePolicy(crew,defaults).message,/^CrewSafío/);assert(!instancePolicy(crew,defaults).message.includes('Kazino'));assert.match(instancePolicy({...crew,access:null},{...defaults,mode:'open'}).message,/CrewSafío/);assert.equal(instancePolicy({...crew,access:{...defaults,message:'Mañana a las ocho'}},defaults).message,'Mañana a las ocho');assert.equal(instancePolicy(item('kazino'),{...defaults,mode:'open'}).mode,'open');});

test.after(()=>fsSync.rmSync(temp,{recursive:true,force:true}));
